/**
 * Pick a delivery window: the days with their windows as radio chips, beside a card with the zone, its price and
 * the buttons. Static markup. Axes: layout (split: the card beside the days, stacked: the days only), item
 * (card, plain), tone.
 */
import { type ReactNode } from "react";
import { Box } from "../primitives/box/box";
import { Button } from "../primitives/button/button";
import { Inline } from "../primitives/inline/inline";
import { List } from "../primitives/list/list";
import { ListItem } from "../primitives/list/list-item";
import { Select } from "../primitives/select/select";
import { SelectOption } from "../primitives/select/select-option";
import { Stack } from "../primitives/stack/stack";
import { Text } from "../primitives/text/text";
import { Field } from "../components/field";
import { SectionFrame } from "../components/section-frame";
import { SlotGrid } from "../components/slot-grid";
import { fmtMoney, tpl } from "../utils";
import type { SlotLabels } from "./slot-board.types";
import type { Day } from "../components/slot-grid.types";
import type { Zone } from "./zone-table.types";

export type SlotBoardProps = {
  id: string;
  title: string;
  lead?: string;
  days: Day[];
  zone: Zone;
  labels: SlotLabels;
  layout?: "split" | "stacked";
  item?: "card" | "plain";
  tone?: "default" | "muted";
  landmarkLabel?: string;
};

export function SlotBoard({
  id,
  title,
  lead = "",
  days,
  zone,
  labels,
  layout = "split",
  item = "card",
  tone = "default",
  landmarkLabel,
}: SlotBoardProps) {
  return (
    <SectionFrame id={id} title={title} lead={lead} tone={tone} landmarkLabel={landmarkLabel}>
      <Box className="grid grid-cols-1 items-start gap-8 lg:grid-cols-3">
        <Box className={(((layout as string) === "split") ? "lg:col-span-2" : "lg:col-span-3")}>
          <SlotGrid days={days} name={tpl("{0}-slot", id)} item={item} />
        </Box>
        {((layout as string) === "split") ? (
          <Stack gap="4" align="stretch" className="rounded bg-card inset-ring inset-ring-border p-6" data-testid="aside">
            <Field label={labels.zone} htmlFor={tpl("{0}-zone", id)}>
              <Select name={tpl("{0}-zone", id)} id={tpl("{0}-zone", id)}>
                <SelectOption value={zone.id} label={zone.name} selected={true} />
              </Select>
            </Field>
            <List tag="ul" className="flex flex-col gap-2">
              <ListItem className="flex items-center justify-between gap-4 text-sm">
                <Inline className="text-muted-foreground">
                  {labels.price}
                </Inline>
                <Inline className="font-medium">
                  {fmtMoney(zone.price, zone.currency)}
                </Inline>
              </ListItem>
              <ListItem className="flex items-center justify-between gap-4 text-sm">
                <Inline className="text-muted-foreground">
                  {labels.freeFrom}
                </Inline>
                <Inline className="font-medium">
                  {fmtMoney(zone.freeFrom, zone.currency)}
                </Inline>
              </ListItem>
              <ListItem className="flex items-center justify-between gap-4 text-sm">
                <Inline className="text-muted-foreground">
                  {labels.time}
                </Inline>
                <Inline className="font-medium">
                  {zone.time}
                </Inline>
              </ListItem>
            </List>
            <Button variant="default" size="default" className="w-full">
              {labels.primary}
            </Button>
            <Button variant="outline" size="default" className="w-full">
              {labels.secondary}
            </Button>
            <Text size="xs" className="text-muted-foreground">
              {labels.note}
            </Text>
          </Stack>
        ) : null}
      </Box>
    </SectionFrame>
  );
}

